type Props = {
  item: ProcessListItemData
  index: number
  itemCount: number
  isOpen: boolean
  canMoveUp: boolean
  canMoveDown: boolean
  onToggleOpen: () => void
  onHeadingChange: (
    itemId: string,
    heading: string,
  ) => void
  onContentChange: (
    itemId: string,
    content: unknown,
  ) => void
  onRemove: (
    itemId: string,
  ) => void
  onMoveUp: () => void
  onMoveDown: () => void
}

export function ProcessListItem({
  item,
  index,
  itemCount,
  isOpen,
  canMoveUp,
  canMoveDown,
  onToggleOpen,
  onHeadingChange,
  onContentChange,
  onRemove,
  onMoveUp,
  onMoveDown,
}: Props) {
  const itemLabel =
    item.heading ||
    `Item ${index + 1}`

  const panelId =
    `process-list-item-${item.id}-fields`

    const rowNumber = String(index + 1).padStart(2, '0')
  return (
    <>
    <div
      id={`content-row-${rowNumber}`}
      className="blocks-field__row-wrap"
    >
      <div className="custom-process-list-card">
        <div className="custom-blocks-field__card">
          <div className="custom-blocks-field__card-header collapsible__toggle-wrap">
            <DragHandle canDrag={true} />
            <button
            type="button"
            className="collapsible__toggle custom-blocks-field__toggle"
            aria-expanded={isOpen}
            aria-controls={panelId}
            onClick={onToggleOpen}
          >
            <span className="visually-hidden">
                Toggle block {rowNumber}
              </span>

            <span
                className={[
                  'collapsible__header-wrap',
                  'collapsible__header-wrap--has-drag-handle',
                  'padding-left-4',
                ]
                  .filter(Boolean)
                  .join(' ')}
              >
                <span className="blocks-field__block-header">
                  <span className="custom-blocks-field__item-index blocks-field__block-number">
                    {rowNumber}
                  </span>

                  <span className="custom-blocks-field__card-text pill pill--style-white pill--size-small blocks-field__block-pill">
                    <span className="custom-blocks-field__card-title pill__label">
                      {itemLabel}
                    </span>
                  </span>

                  <span className="custom-blocks-field__card-subtitle section-title">
                    
                  </span>
                </span>
              </span>

              <span className="collapsible__indicator" aria-hidden="true">
                <svg
                  className={[
                    'icon',
                    'icon--chevron',
                    isOpen && 'expanded-icon',
                  ]
                    .filter(Boolean)
                    .join(' ')}
                  height="100%"
                  viewBox="0 0 20 20"
                  width="100%"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    className="stroke"
                    d="M14 8L10 12L6 8"
                    strokeLinecap="square"
                  />
                </svg>
              </span>
          </button>
          </div>
        </div>
      </div>

    </div>
    <article className="custom-blocks-field__process-list-item">
      

      {isOpen ? (
        <div
          id={panelId}
          className="custom-blocks-field__process-list-item-fields collapsible__content render-fields"
        >
          <div className="usa-form-group field-type text">
            <label
              htmlFor={`process-list-heading-${item.id}`}
              className="field-label"
            >
              Heading
            </label>

            <input
              id={`process-list-heading-${item.id}`}
              className="usa-input"
              type="text"
              value={item.heading}
              onChange={(event) =>
                onHeadingChange(
                  item.id,
                  event.target.value,
                )
              }
            />
          </div>

          <div className="custom-blocks-field__process-list-item-content">
            <label className="field-label">
              Content
            </label>

            <InlineRichTextField
              value={item.content}
              onChange={(content) =>
                onContentChange(
                  item.id,
                  content,
                )
              }
              showBlocksMenu={false}
            />
          </div>
        </div>
      ) : null}
    </article>
    </>
  )
}
